package deploy

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/kustomize"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"gopkg.in/yaml.v3"
)

// kustomizeBuild is the seam unit tests replace to avoid the kustomize
// binary; production wires kustomize.Client.Build.
var kustomizeBuild = func(ctx context.Context, runner command.Runner, dir string) ([]byte, error) {
	return kustomize.Client{Runner: runner}.Build(ctx, dir)
}

// localEnv is the only environment a local render knows. It names the overlay
// the templates ship for the local cluster and lands in .gitops.env.
const localEnv = "local"

// localRegistry is the placeholder registry a local render reports. Every
// Deployment image is overridden by the root kustomization's images[] entries,
// so the rendered registry is never pulled from.
const localRegistry = "dev"

// localImageTag is the conventional tag the k3s scripts build and load
// component images under.
const localImageTag = "dev"

// localExclusionReason is the when-condition on the repo-metadata exclusion
// rules a local render prepends. It is the literal "false": the filter's
// truthy() treats any other non-empty string as true, so a prose reason here
// would *include* the matched files — the bug that let component.yaml and
// every conditional variant into local renders.
const localExclusionReason = "false"

// LocalOptions configures Local.
//
// There are no value files and no --set, deliberately: every fact the
// templates need is derived (topology, scaffold records, local constants,
// .intropy/local.yaml), and an escape hatch would let one developer's render
// diverge from the team's checked-in state. There is no Environment either —
// a local render is always the local overlay.
type LocalOptions struct {
	// System names the system to render. It selects which system host to read
	// the topology from when a workspace holds several. Empty means the only
	// host in the workspace, named by whatever its topology declares.
	System string

	// Namespace is the target namespace in the emitted manifests. Empty
	// defaults to the system name.
	Namespace string

	// Images overrides image references, repeatable. "<component>=<name:tag>"
	// overrides one component's entry; ":<tag>" (leading colon) retags every
	// component — the release-candidate flow.
	Images []string

	// NoInput fails instead of prompting when a connector has no recorded
	// binding or a template parameter has no derivable value.
	NoInput bool

	// TemplateVersion pins the template library release.
	TemplateVersion string

	// TopologyFile reads the record from a file instead of running the host's
	// graph verb; "-" reads stdin. Internal test seam — not exposed as a CLI flag.
	TopologyFile string

	// SourceDir is where system hosts and scaffold records are discovered, and
	// where .intropy/local.yaml lives. Internal test seam — the CLI always
	// runs from the workspace root.
	SourceDir string

	// Runner drives the kustomize binary.
	Runner command.Runner

	UserAgent string

	// Owner and Repo select the template library; zero values target the
	// official library. GitHubBaseURL is a test-only seam.
	Owner         string
	Repo          string
	GitHubBaseURL string
	HTTP          *http.Client

	Stdin  io.Reader
	Stdout io.Writer
	Stderr io.Writer
}

func (o *LocalOptions) applyDefaults() {
	if o.Runner == nil {
		o.Runner = git.DefaultRunner()
	}
	if o.SourceDir == "" {
		o.SourceDir = "."
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
	if o.Stdin == nil {
		o.Stdin = os.Stdin
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
}

// localFacts is what newInitFacts becomes when there is no GitOps repository
// to derive from: the environments, registry and platform are constants of the
// local cluster the k3s scripts install, and the domain is omitted entirely.
type localFacts struct {
	System    string
	Model     InitModel
	Scaffolds map[string]template.ScaffoldEntry
}

func newLocalFacts(opts LocalOptions, found discoveredTopology) (localFacts, error) {
	topo := found.Topology

	system := opts.System
	if system == "" {
		system = topo.System
	}
	if system == "" {
		return localFacts{}, fmt.Errorf("the topology record names no system; pass --system")
	}
	if err := assertPathSegment("--system", system); err != nil {
		return localFacts{}, err
	}

	model := newInitModel(topo, found.Scaffolds)
	for _, c := range model.Components {
		// From the topology record, which is generated by a build this CLI does
		// not own: a name with a separator in it would render into a directory
		// of its own choosing.
		if err := assertPathSegment("component name", c.Name); err != nil {
			return localFacts{}, err
		}
		if c.Dir == "" {
			fmt.Fprintf(opts.Stderr, "warning: %s has no scaffold record under the workspace root; its manifests will be generated without an appId or sourcePaths\n", c.Name)
		}
	}

	return localFacts{
		System:    system,
		Model:     model,
		Scaffolds: matchScaffolds(topo.Components, found.Scaffolds),
	}, nil
}

// gitopsMap is the reserved .gitops map for a local render. Fields that have
// no local meaning — domain, the ArgoCD app namespace — are present but empty,
// and the fixture contract forbids the local overlay's skeletons from
// referencing them. registry is the placeholder the root kustomization's
// images[] entries make irrelevant.
func (f localFacts) gitopsMap(component string) map[string]any {
	return map[string]any{
		"domain":             "",
		"system":             f.System,
		"component":          component,
		"env":                localEnv,
		"host":               HostDirName,
		"registry":           localRegistry,
		"argocdAppNamespace": "",
		"environments":       []string{localEnv},
		"platform": map[string]any{
			"provider":    "kubernetes",
			"pubsub":      "redis",
			"secretStore": "kubernetes",
		},
	}
}

// scaffoldValues mirrors initFacts.scaffoldValues: an empty map rather than a
// missing key, so a skeleton reading .scaffold.x never fails on a missing record.
func (f localFacts) scaffoldValues(component string) map[string]any {
	if s, ok := f.Scaffolds[component]; ok && s.Values != nil {
		return s.Values
	}
	return map[string]any{}
}

// imageOverride is one parsed --image entry: a per-component newName/newTag
// pair, or a global newTag when Component is empty.
type imageOverride struct {
	Component string
	NewName   string
	NewTag    string
}

// parseImageOverrides parses the --image grammar: "<component>=<name:tag>" for
// one component, ":<tag>" for all of them. Anything else is a usage error
// showing both forms.
func parseImageOverrides(args []string) ([]imageOverride, error) {
	var out []imageOverride
	for _, arg := range args {
		if strings.HasPrefix(arg, ":") {
			tag := strings.TrimPrefix(arg, ":")
			if tag == "" || strings.ContainsAny(tag, "=:") {
				return nil, invalidImageOverride(arg)
			}
			out = append(out, imageOverride{NewTag: tag})
			continue
		}
		component, ref, found := strings.Cut(arg, "=")
		name, tag, tagged := strings.Cut(ref, ":")
		if !found || component == "" || !tagged || name == "" || tag == "" || strings.Contains(tag, ":") {
			return nil, invalidImageOverride(arg)
		}
		out = append(out, imageOverride{Component: component, NewName: name, NewTag: tag})
	}
	return out, nil
}

func invalidImageOverride(arg string) error {
	return fmt.Errorf("invalid --image %q\nvalid forms: --image <component>=<name:tag> to override one component, --image :<tag> to retag every component", arg)
}

// Local renders a system's deployable manifests for the local development
// cluster and writes the multi-document YAML to opts.Stdout.
//
// The render is unconditional: fixture servers are always installed on the
// local cluster by the k3s scripts, so the only decision this command makes is
// which fixture each connector binds to, recorded in .intropy/local.yaml.
// Nothing else is written — no git, no branches — and the command never
// inspects the cluster: it renders, kubectl applies, a missing cluster fails
// at apply time with kubectl's own error.
func Local(ctx context.Context, opts LocalOptions) error {
	opts.applyDefaults()

	overrides, err := parseImageOverrides(opts.Images)
	if err != nil {
		return err
	}

	found, err := resolveInitTopology(ctx, InitOptions{
		System:       opts.System,
		TopologyFile: opts.TopologyFile,
		SourceDir:    opts.SourceDir,
		Stdin:        opts.Stdin,
		Stderr:       opts.Stderr,
	})
	if err != nil {
		return err
	}

	facts, err := newLocalFacts(opts, found)
	if err != nil {
		return err
	}
	namespace := opts.Namespace
	if namespace == "" {
		namespace = facts.System
	}

	lib, err := template.FetchLibrary(ctx, template.LibraryOptions{
		Version:       opts.TemplateVersion,
		HTTP:          opts.HTTP,
		UserAgent:     opts.UserAgent,
		Stderr:        opts.Stderr,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		GitHubBaseURL: opts.GitHubBaseURL,
	})
	if err != nil {
		return err
	}
	defer lib.Close()

	// The catalog comes from the fetched release, so the menu, the validation
	// and the rendered binding skeletons can never drift apart.
	catalog, err := fixtureCatalog(lib)
	if err != nil {
		return err
	}

	bindings, err := resolveConnectorBindings(opts, facts, catalog)
	if err != nil {
		return err
	}

	staging, err := os.MkdirTemp("", "intropy-int-local-*")
	if err != nil {
		return fmt.Errorf("create staging directory: %w", err)
	}
	defer os.RemoveAll(staging)

	fmt.Fprintf(opts.Stderr, "rendering %s for local\n", facts.System)
	if err := renderLocal(opts, facts, bindings, lib, staging); err != nil {
		return err
	}

	images, err := localImageEntries(facts, overrides)
	if err != nil {
		return err
	}
	if err := writeLocalRootKustomization(staging, namespace, facts, images); err != nil {
		return err
	}

	built, err := kustomizeBuild(ctx, opts.Runner, staging)
	if err != nil {
		return err
	}
	if err := assertAllImagesTagged(built); err != nil {
		return err
	}
	if _, err := opts.Stdout.Write(built); err != nil {
		return fmt.Errorf("write manifests: %w", err)
	}
	return nil
}

// fixtureCatalog reads the closed fixture catalog from the fetched
// deploy-component template. A release without one cannot render bindings, so
// it is a hard error naming the release rather than a menu with no choices.
func fixtureCatalog(lib *template.Library) ([]string, error) {
	tmpl, _, err := lib.Open(TemplateDeployComponent)
	if err != nil {
		return nil, err
	}
	if tmpl.Spec.Local == nil || len(tmpl.Spec.Local.Fixtures) == 0 {
		return nil, fmt.Errorf("%s declares no fixture catalog (spec.local.fixtures on %s)\nuse --template-version to pin a library release that ships one", lib.Ref(), TemplateDeployComponent)
	}
	return tmpl.Spec.Local.Fixtures, nil
}

// resolveConnectorBindings loads the recorded bindings, prompts for the
// unbound ones against the fetched catalog, notes stale entries, and writes
// the file back only if an answer changed.
func resolveConnectorBindings(opts LocalOptions, facts localFacts, catalog []string) (map[string]string, error) {
	path := localConfigPath(opts.SourceDir)
	cfg, err := loadLocalConfig(path)
	if err != nil {
		return nil, err
	}

	// NewMenuPrompter rather than SelectPrompter: the connector question is
	// answered from piped stdin in tests and scripts too, and --no-input is
	// still what turns prompting off. The answer is persisted to a checked-in
	// file, so a piped answer is as reviewable as a typed one.
	var prompter *template.MenuPrompter
	if !opts.NoInput {
		prompter = template.NewMenuPrompter(opts.Stdin, opts.Stderr)
	}
	bindings := map[string]string{}
	changed := false
	for _, conn := range facts.Model.Connectors {
		choice, recorded := cfg.Bindings[conn.Name]
		if recorded {
			if !slices.Contains(catalog, choice) {
				return nil, fmt.Errorf("connector %s is bound to %q in %s, which %s does not offer; the catalog is: %s\nedit the file, or delete the entry to be asked again",
					conn.Name, choice, path, TemplateDeployComponent, strings.Join(catalog, ", "))
			}
			bindings[conn.Name] = choice
			continue
		}
		if prompter == nil {
			return nil, fmt.Errorf("connector %s has no local binding in %s\nrun 'intropy int local %s' interactively, or add it to the file",
				conn.Name, path, facts.System)
		}
		heading := fmt.Sprintf("connector %s (external system %s) — which binding?", conn.Name, conn.ExternalSystem)
		choice, err := prompter.Select(heading, catalog)
		if err != nil {
			return nil, fmt.Errorf("read binding for connector %s: %w", conn.Name, err)
		}
		bindings[conn.Name] = choice
		changed = true
	}
	for name := range cfg.Bindings {
		if !slices.ContainsFunc(facts.Model.Connectors, func(c InitConnector) bool { return c.Name == name }) {
			fmt.Fprintf(opts.Stderr, "note: local.yaml binds %s, which the topology no longer declares\n", name)
		}
	}

	if !changed {
		return bindings, nil
	}
	merged := map[string]string{}
	for k, v := range cfg.Bindings {
		merged[k] = v
	}
	for k, v := range bindings {
		merged[k] = v
	}
	if err := saveLocalConfig(path, localConfig{Bindings: merged}); err != nil {
		return nil, err
	}
	fmt.Fprintf(opts.Stderr, "recorded local bindings in %s\n", path)
	return bindings, nil
}

// renderLocal renders the host template once and the component template once
// per component, into a flat staging tree: no domain or system segment,
// because the temp root already holds exactly one system.
func renderLocal(opts LocalOptions, facts localFacts, bindings map[string]string, lib *template.Library, staging string) error {
	if err := renderLocalOne(opts, facts, bindings, lib, TemplateDeployHost, HostDirName, nil, staging); err != nil {
		return err
	}
	for _, c := range facts.Model.Components {
		comp := c
		if err := renderLocalOne(opts, facts, bindings, lib, TemplateDeployComponent, c.Name, &comp, staging); err != nil {
			return err
		}
	}
	return nil
}

// renderLocalOne renders one unit for the local environment. Unlike deploy
// init there is exactly one environment, so no per-env pass and no
// mergeRendered: the render lands in the staged tree directly.
func renderLocalOne(opts LocalOptions, facts localFacts, bindings map[string]string, lib *template.Library, templateName, dirName string, comp *InitComponent, staging string) error {
	tmpl, skeleton, err := lib.Open(templateName)
	if err != nil {
		return err
	}

	values, err := resolveLocalValues(opts, facts, bindings, tmpl, dirName, comp)
	if err != nil {
		return fmt.Errorf("%s for %s: %w", templateName, dirName, err)
	}

	dest := filepath.Join(staging, dirName)
	if err := os.MkdirAll(dest, 0o755); err != nil {
		return err
	}
	if err := template.RenderFiltered(skeleton, dest, values, localFileRules(tmpl.Spec.Files)); err != nil {
		return fmt.Errorf("render %s for %s: %w", templateName, dirName, err)
	}
	return nil
}

// resolveLocalValues layers the derived facts under a prompt for anything
// still missing, then injects the reserved structures. There are deliberately
// no value files and no --set: a local render must be reproducible from the
// team's checked-in state.
func resolveLocalValues(opts LocalOptions, facts localFacts, bindings map[string]string, tmpl *template.Template, dirName string, comp *InitComponent) (map[string]any, error) {
	base := seedDeclaredParams(tmpl, localSeeds(facts, dirName, comp))

	prompter := template.AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
	values, err := template.ResolveLayered(tmpl, base, nil, opts.Stdin, nil, prompter)
	if err != nil {
		return nil, err
	}

	model, err := facts.Model.asMap()
	if err != nil {
		return nil, err
	}
	local, err := toMap(localModel{Bindings: bindings})
	if err != nil {
		return nil, err
	}
	reserved := map[string]any{
		template.ReservedEnvKey:      localEnv,
		template.ReservedTopologyKey: model,
		template.ReservedGitopsKey:   facts.gitopsMap(dirName),
		template.ReservedLocalKey:    local,
	}
	if comp != nil {
		componentMap, err := toMap(comp)
		if err != nil {
			return nil, err
		}
		reserved[template.ReservedComponentKey] = componentMap
		reserved[template.ReservedScaffoldKey] = facts.scaffoldValues(comp.Name)
	}
	if err := template.InjectReserved(tmpl, values, reserved); err != nil {
		return nil, err
	}
	return values, nil
}

// localModel is the reserved .local structure: the per-connector fixture
// bindings decided by this command.
type localModel struct {
	Bindings map[string]string `json:"bindings"`
}

// localSeeds is initSeeds with local constants in place of the GitOps facts.
// Domain is omitted rather than blank, so a template that declares it required
// surfaces a prompt instead of silently rendering an empty tree segment.
func localSeeds(facts localFacts, dirName string, comp *InitComponent) map[string]any {
	seeds := map[string]any{
		"system":      facts.System,
		"hostName":    HostDirName,
		"registry":    localRegistry,
		"provider":    "kubernetes",
		"pubsub":      "redis",
		"secretStore": "kubernetes",
	}
	// Only when unambiguous, as on deploy init.
	if len(facts.Model.PubSubs) == 1 {
		seeds["pubsubName"] = facts.Model.PubSubs[0].Name
	}
	if comp != nil {
		seeds["name"] = comp.Name
		seeds["kind"] = comp.Kind
		seeds["appId"] = comp.AppID
		seeds["workload"] = comp.Workload
		if comp.Dir != "" {
			seeds["sourceDir"] = comp.Dir
		}
	} else {
		seeds["name"] = dirName
		seeds["appId"] = dirName
	}
	return seeds
}

// localFileRules narrows a template's file rules to manifests only: an
// exclusion for the repo-metadata paths, prepended so it decides first,
// ahead of the template's own rules. Those rules are kept — with the local
// facts seeded (pubsub redis, the block's workload, secretStore kubernetes)
// they select the same variants a local render needs, and they are what keeps
// the generic overlays/{{ .env }}/ skeleton from rendering over the local
// overlay.
func localFileRules(rules []template.FileRule) []template.FileRule {
	out := make([]template.FileRule, 0, len(localRepoMetadataGlobs)+len(rules))
	for _, glob := range localRepoMetadataGlobs {
		out = append(out, template.FileRule{Path: glob, When: localExclusionReason})
	}
	return append(out, rules...)
}

// localRepoMetadataGlobs are the skeleton paths a local render never emits:
// repo metadata the rest of deploy reads, not Kubernetes manifests. The
// fixture-contract doc in the templates repo enumerates the same list.
var localRepoMetadataGlobs = []string{"component.yaml.tmpl"}

// localImageEntry is one images[] entry in the root kustomization.
type localImageEntry struct {
	Name    string `yaml:"name"`
	NewName string `yaml:"newName,omitempty"`
	NewTag  string `yaml:"newTag,omitempty"`
}

// localImageEntries resolves the images[] list: one entry per component, host
// excluded — the same fact requirePinnable encodes (the host is shared and
// declares no image). Each rendered reference is exactly the component name,
// the shape the fixture contract pins, so name matching cannot silently miss.
func localImageEntries(facts localFacts, overrides []imageOverride) ([]localImageEntry, error) {
	perComponent := map[string]imageOverride{}
	var global *imageOverride
	for _, o := range overrides {
		if o.Component == "" {
			g := o
			global = &g
			continue
		}
		perComponent[o.Component] = o
	}

	known := map[string]bool{}
	for _, c := range facts.Model.Components {
		known[c.Name] = true
	}
	var names []string
	for name := range perComponent {
		if !known[name] {
			names = append(names, name)
		}
	}
	if len(names) > 0 {
		slices.Sort(names)
		return nil, fmt.Errorf("--image names %s, which the topology does not declare as a component", strings.Join(names, ", "))
	}

	entries := make([]localImageEntry, 0, len(facts.Model.Components))
	for _, c := range facts.Model.Components {
		e := localImageEntry{Name: c.Name, NewTag: localImageTag}
		if o, ok := perComponent[c.Name]; ok {
			e.NewName = o.NewName
			e.NewTag = o.NewTag
		} else if global != nil {
			e.NewTag = global.NewTag
		}
		entries = append(entries, e)
	}
	return entries, nil
}

// localRootKustomization is the root kustomization the CLI writes after
// rendering: the only place namespace and the conventional image tags are
// applied, so templates stay namespace-agnostic and never hardcode a tag.
type localRootKustomization struct {
	APIVersion string            `yaml:"apiVersion"`
	Kind       string            `yaml:"kind"`
	Namespace  string            `yaml:"namespace"`
	Resources  []string          `yaml:"resources"`
	Images     []localImageEntry `yaml:"images,omitempty"`
}

func writeLocalRootKustomization(staging, namespace string, facts localFacts, images []localImageEntry) error {
	k := localRootKustomization{
		APIVersion: "kustomize.config.k8s.io/v1beta1",
		Kind:       "Kustomization",
		Namespace:  namespace,
		Resources:  []string{HostDirName + "/overlays/" + localEnv},
		Images:     images,
	}
	for _, c := range facts.Model.Components {
		k.Resources = append(k.Resources, c.Name+"/overlays/"+localEnv)
	}
	data, err := yaml.Marshal(k)
	if err != nil {
		return fmt.Errorf("encode root kustomization: %w", err)
	}
	if err := os.WriteFile(filepath.Join(staging, "kustomization.yaml"), data, 0o644); err != nil {
		return fmt.Errorf("write root kustomization: %w", err)
	}
	return nil
}

// assertAllImagesTagged is the belt-and-braces check against template drift:
// kustomize silently ignores an images[] entry whose name matches nothing, so
// a drifted image-reference convention would otherwise ship an unoverridden —
// and therefore untagged — image with no error until pull time.
func assertAllImagesTagged(manifest []byte) error {
	dec := yaml.NewDecoder(bytes.NewReader(manifest))
	for {
		var doc struct {
			Kind string `yaml:"kind"`
			Spec struct {
				Template struct {
					Spec struct {
						Containers []struct {
							Image string `yaml:"image"`
						} `yaml:"containers"`
					} `yaml:"spec"`
				} `yaml:"template"`
			} `yaml:"spec"`
		}
		if err := dec.Decode(&doc); err != nil {
			if err == io.EOF {
				return nil
			}
			return fmt.Errorf("parse rendered manifests: %w", err)
		}
		if doc.Kind != "Deployment" {
			continue
		}
		for _, c := range doc.Spec.Template.Spec.Containers {
			if c.Image == "" {
				continue
			}
			if !strings.Contains(c.Image, ":") && !strings.Contains(c.Image, "@") {
				return fmt.Errorf("a Deployment renders image %q without a tag\nkustomize overrides match on the exact rendered name; the local overlay's image reference convention (<component>:dev) may have drifted", c.Image)
			}
		}
	}
}

package deploy

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/huandu/xstrings"
	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// The templates deploy init renders. They are separate packages because they
// render a different number of times — once per system, once per component —
// into different directories, from different value sets.
const (
	TemplateDeployHost      = "deploy-host"
	TemplateDeployComponent = "deploy-component"
)

// HostDirName is the component directory holding a system's shared manifests.
//
// A Dapr Component is namespace-scoped and every integration in a customer's
// namespace shares it, so exactly one ArgoCD Application may own each one. The
// system host is what gives them that owner: it has no Dockerfile and therefore
// no image, which is precisely what gitops.KindShared describes.
const HostDirName = "host"

// initBranchPrefix namespaces the branches this command pushes.
const initBranchPrefix = "deploy-init/"

// runGraph is the seam tests replace to avoid a dotnet build.
var runGraph = topology.RunGraph

// InitOptions configures Init.
//
// There is no Environment: overlays are created for every environment the
// repository defines unless Environments narrows it. There is no AllowDirty, no
// NoWait and no Timeout either — no source working tree is read for correctness,
// and nothing is synced.
type InitOptions struct {
	// Components narrows the run to named topology components. Empty means the
	// whole system, host included.
	Components []string

	// Domain places the system in the GitOps tree. Unlike every other deploy
	// subcommand's --domain this is a destination rather than a filter. Empty is
	// inferred when exactly one domain already holds the system.
	Domain string

	// System names the system to scaffold.
	//
	// It does two things, which are the same thing said once: it selects which
	// system host to read the topology from when a workspace holds several, and
	// it is the tree segment. Empty means the only host in the workspace, named
	// by whatever its topology declares.
	System string

	// Environments selects which overlays to create. Empty means every
	// environment in deploy.yaml.
	Environments []string

	// TopologyFile reads the record from a file instead of running the host's
	// graph verb; "-" reads stdin. Internal test seam — not exposed as a CLI flag.
	TopologyFile string

	// SourceDir is where system hosts and scaffold records are discovered.
	// Internal test seam — not exposed as a CLI flag.
	SourceDir string

	// TemplateVersion pins the template library release.
	TemplateVersion string

	// Files, SetValues, NoInput and Stdin are the value layering, identical to
	// int create.
	Files     []string
	SetValues map[string]any
	NoInput   bool
	Stdin     io.Reader

	// PlanOnly resolves, renders and classifies, then reports without writing
	// anything or touching git.
	PlanOnly bool

	// Force overwrites files that already differ, subject to the pinned-digest
	// guard in assertForceIsSafe.
	Force bool

	GitopsRepo   string
	OutputFormat string
	Color        bool
	CacheRoot    string

	Runner     command.Runner
	UserAgent  string
	CliVersion string
	Stdout     io.Writer
	Stderr     io.Writer

	// Owner and Repo select the template library; zero values target the
	// official library. GitHubBaseURL is a test-only seam.
	Owner         string
	Repo          string
	GitHubBaseURL string
	HTTP          *http.Client
}

func (o InitOptions) output() output {
	return output{Format: o.OutputFormat, Color: o.Color, Stdout: o.Stdout, Stderr: o.Stderr}
}

func (o InitOptions) session() sessionOptions {
	return sessionOptions{
		GitopsRepo: o.GitopsRepo,
		CacheRoot:  o.CacheRoot,
		Runner:     o.Runner,
		Stderr:     o.Stderr,
	}
}

func (o *InitOptions) applyDefaults() {
	if o.Runner == nil {
		o.Runner = git.DefaultRunner()
	}
	if o.SourceDir == "" {
		o.SourceDir = "."
	}
	if o.OutputFormat == "" {
		o.OutputFormat = OutputPlain
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
	if o.Stdin == nil {
		o.Stdin = os.Stdin
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
}

// Init scaffolds a system's manifests into the GitOps repository.
//
// The sequencing matters more than it looks. The topology is resolved *before*
// the session is opened, because openSession takes a non-blocking exclusive lock
// on the shared cached checkout and the graph verb can take minutes on a cold
// project — holding the lock across that would fail every colleague's deploy
// outright. Nothing is written until every file has been classified, and nothing
// is pushed to the default branch: a tree full of placeholders would be picked up
// by the ApplicationSet immediately.
func Init(ctx context.Context, opts InitOptions) error {
	opts.applyDefaults()
	out := opts.output()

	found, err := resolveInitTopology(ctx, opts)
	if err != nil {
		return err
	}

	s, err := openSession(ctx, opts.session(), "git")
	if err != nil {
		return err
	}
	defer s.Close()

	facts, err := newInitFacts(opts, s, found)
	if err != nil {
		return err
	}

	staging, err := os.MkdirTemp("", "intropy-deploy-init-*")
	if err != nil {
		return fmt.Errorf("create staging directory: %w", err)
	}
	defer os.RemoveAll(staging)

	// Opened once, and every read of and write to the checkout goes through it:
	// the manifests come from a repository this CLI does not control, and the
	// tree segments come from flags.
	dest, err := openDestTree(s.repo.Root)
	if err != nil {
		return err
	}
	defer dest.Close()

	libraryRef, err := renderScaffold(ctx, opts, facts, staging)
	if err != nil {
		return err
	}
	branch := initBranchPrefix + facts.Domain + "-" + facts.System

	rels, err := stageRels(staging)
	if err != nil {
		return err
	}
	actions, err := classifyStaged(staging, dest, rels, opts.Force)
	if err != nil {
		return err
	}
	if opts.Force {
		if err := assertForceIsSafe(s.repo.Root, actions); err != nil {
			return err
		}
	}

	result := InitResult{
		System:       facts.System,
		Domain:       facts.Domain,
		Host:         HostDirName,
		Template:     libraryRef,
		Components:   facts.ComponentNames(),
		Files:        actions,
		Applied:      false,
		Placeholders: nil,
	}

	if opts.PlanOnly {
		// Scan the staging tree: the files are not in the repository yet, so the
		// only place the placeholders exist is where they were rendered.
		result.Placeholders, err = scanPlaceholders(staging, rels)
		if err != nil {
			return err
		}
		return reportInit(out, result, actions, true)
	}

	if writes(actions) == 0 {
		// Nothing to write, but the placeholders already in the repository are
		// still the answer to "what is left to do here".
		result.Placeholders, err = scanPlaceholders(s.repo.Root, rels)
		if err != nil {
			return err
		}
		return reportInit(out, result, actions, false)
	}

	published, err := publishScaffold(ctx, opts, s.repo, publishScaffoldOptions{
		StagingDir: staging,
		Dest:       dest,
		Actions:    actions,
		Rels:       rels,
		Branch:     branch,
		Facts:      facts,
	})
	if err != nil {
		return err
	}
	result.Applied = true
	result.Branch = branch
	result.Revision = published.Revision
	result.Placeholders = published.Placeholders

	return reportInit(out, result, actions, false)
}

func writes(actions []FileAction) int {
	n := 0
	for _, a := range actions {
		if a.Writes() {
			n++
		}
	}
	return n
}

// discoveredTopology is what resolveInitTopology found in the workspace.
type discoveredTopology struct {
	Topology  *topology.Topology
	Scaffolds []template.ScaffoldEntry

	// HostDir is the system host the record came from. Its path is the best
	// source for the domain.
	HostDir string
}

// resolveInitTopology obtains the record and the workspace's scaffold records.
func resolveInitTopology(ctx context.Context, opts InitOptions) (discoveredTopology, error) {
	scaffolds, warnings := template.ListScaffolds(opts.SourceDir)
	for _, w := range warnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}

	if opts.TopologyFile != "" {
		r := opts.Stdin
		if opts.TopologyFile != "-" {
			f, err := os.Open(opts.TopologyFile)
			if err != nil {
				return discoveredTopology{}, fmt.Errorf("read topology: %w", err)
			}
			defer f.Close()
			r = f
		}
		topo, err := topology.Decode(r)
		if err != nil {
			return discoveredTopology{}, fmt.Errorf("read topology %s: %w", opts.TopologyFile, err)
		}
		return discoveredTopology{Topology: topo, Scaffolds: scaffolds}, nil
	}

	var hosts []template.ScaffoldEntry
	for _, s := range scaffolds {
		if s.Role == template.RoleSystemHost {
			hosts = append(hosts, s)
		}
	}
	host, err := selectHost(hosts, opts.System, opts.SourceDir)
	if err != nil {
		return discoveredTopology{}, err
	}

	// Said before starting, not after: a silent multi-minute wait reads as a hang.
	fmt.Fprintf(opts.Stderr, "reading topology from %s (building first; this can take a minute)\n", host.Path)
	topo, err := runGraph(ctx, host.Path)
	if err != nil {
		return discoveredTopology{}, fmt.Errorf("%s: %w", host.Path, err)
	}
	if opts.System != "" && topo.System != "" && opts.System != topo.System {
		// Not an error: --system names the system, and a caller who asked for a
		// different name gets it. Worth saying out loud, because it silently
		// decides the tree segment.
		fmt.Fprintf(opts.Stderr, "warning: the topology declares system %q; using %q as the tree segment\n", topo.System, opts.System)
	}
	return discoveredTopology{Topology: topo, Scaffolds: scaffolds, HostDir: host.Path}, nil
}

// selectHost picks which system host to read the topology from.
//
// Selection is by name and costs nothing: a scaffolded host records the system
// name in its own record, and its parent directory is the system directory. Both
// are on disk, so a multi-system workspace does not have to build every host to
// find out which one was meant.
//
// With no --system and one host, that host. With no --system and several, an
// error — picking one arbitrarily would scaffold the wrong system.
func selectHost(hosts []template.ScaffoldEntry, system, sourceDir string) (template.ScaffoldEntry, error) {
	if len(hosts) == 0 {
		return template.ScaffoldEntry{}, fmt.Errorf("no system host found under %s; run this from a system workspace", sourceDir)
	}

	if system != "" {
		var matches []template.ScaffoldEntry
		for _, h := range hosts {
			if matchesSystemName(h, system) {
				matches = append(matches, h)
			}
		}
		switch len(matches) {
		case 1:
			return matches[0], nil
		case 0:
			// A single host and no match is the older meaning of --system: rename
			// the tree segment rather than select anything. Still useful, and
			// unambiguous when there is only one system to talk about.
			if len(hosts) == 1 {
				return hosts[0], nil
			}
			return template.ScaffoldEntry{}, fmt.Errorf("no system host named %q under %s.\nFound:\n%s",
				system, sourceDir, describeHosts(hosts))
		default:
			return template.ScaffoldEntry{}, fmt.Errorf("%q matches %d system hosts, so it does not say which one:\n%s",
				system, len(matches), describeHosts(matches))
		}
	}

	if len(hosts) == 1 {
		return hosts[0], nil
	}
	return template.ScaffoldEntry{}, fmt.Errorf("%s holds %d system hosts; pass --system to pick one:\n%s",
		sourceDir, len(hosts), describeHosts(hosts))
}

// matchesSystemName reports whether a host is the one the caller named.
//
// Three keys are tried, in descending reliability: the record's own name (what
// sys create writes), the system directory holding the host, and the host
// directory itself — which is often a generic "system-host" and so the weakest.
func matchesSystemName(h template.ScaffoldEntry, system string) bool {
	want := normalizeSystemName(system)
	keys := []string{
		scaffoldString(h, "name"),
		filepath.Base(filepath.Dir(h.Path)),
		filepath.Base(h.Path),
	}
	for _, k := range keys {
		if k != "" && normalizeSystemName(k) == want {
			return true
		}
	}
	return false
}

// normalizeSystemName folds the spellings that mean the same system. sys create
// kebab-cases whatever it is given, so OrderFlow and order-flow are the same
// system and must select the same host.
func normalizeSystemName(s string) string {
	return strings.ToLower(xstrings.ToKebabCase(s))
}

func describeHosts(hosts []template.ScaffoldEntry) string {
	lines := make([]string, 0, len(hosts))
	for _, h := range hosts {
		name := scaffoldString(h, "name")
		if name == "" {
			name = filepath.Base(filepath.Dir(h.Path))
		}
		lines = append(lines, fmt.Sprintf("  %s  (%s)", name, h.Path))
	}
	slices.Sort(lines)
	return strings.Join(lines, "\n")
}

// initFacts is everything derived before rendering: where the manifests go, what
// the platform is, and the model the skeletons range over.
type initFacts struct {
	Domain string
	System string

	Environments []string
	Registry     string
	AppNamespace string
	Platform     gitops.PlatformConfig

	Model     InitModel
	Scaffolds map[string]template.ScaffoldEntry
	Selected  []InitComponent
}

func (f initFacts) ComponentNames() []string {
	names := make([]string, 0, len(f.Selected))
	for _, c := range f.Selected {
		names = append(names, c.Name)
	}
	return names
}

func newInitFacts(opts InitOptions, s *session, found discoveredTopology) (initFacts, error) {
	topo, scaffolds := found.Topology, found.Scaffolds

	system := opts.System
	if system == "" {
		system = topo.System
	}
	if system == "" {
		return initFacts{}, fmt.Errorf("the topology record names no system; pass --system")
	}

	domain, err := resolveInitDomain(s.repo.Root, opts.Domain, system, found.HostDir, scaffolds, opts.Stderr)
	if err != nil {
		return initFacts{}, err
	}

	// Both become tree segments and both end up in the branch name, so neither
	// may be anything but a single name. destTree refuses a traversal at the
	// write; failing here instead names the input that was wrong.
	if err := assertPathSegment("--domain", domain); err != nil {
		return initFacts{}, err
	}
	if err := assertPathSegment("--system", system); err != nil {
		return initFacts{}, err
	}

	environments, err := selectEnvironments(s.deployCfg, opts.Environments)
	if err != nil {
		return initFacts{}, err
	}

	model := newInitModel(topo, scaffolds)
	selected, err := selectComponents(model, opts.Components, system)
	if err != nil {
		return initFacts{}, err
	}
	for _, c := range selected {
		// From the topology record, which is generated by a build this CLI does
		// not own: a name with a separator in it would render into a directory of
		// its own choosing.
		if err := assertPathSegment("component name", c.Name); err != nil {
			return initFacts{}, err
		}
		if c.Dir == "" {
			fmt.Fprintf(opts.Stderr, "warning: %s has no scaffold record under the workspace root; its manifests will be generated without an appId or sourcePaths\n", c.Name)
		}
	}

	return initFacts{
		Domain:       domain,
		System:       system,
		Environments: environments,
		Registry:     s.deployCfg.Registry,
		AppNamespace: s.deployCfg.Argocd.AppNamespace,
		Platform:     s.deployCfg.Platform,
		Model:        model,
		Scaffolds:    matchScaffolds(topo.Components, scaffolds),
		Selected:     selected,
	}, nil
}

// resolveInitDomain places the system in the tree.
//
// The topology itself says nothing about which business domain a system belongs
// to, but two other things do, and between them --domain is rarely needed:
//
//   - where the system already is in the GitOps tree, which is authoritative —
//     a re-run must land where the component actually lives;
//   - the source workspace's own layout, which every customer integrations tree
//     mirrors from the deployment tree: domains/<domain>/<system>/<project>.
//
// An explicit --domain always wins, and is still required when neither holds.
func resolveInitDomain(root, flag, system, hostDir string, scaffolds []template.ScaffoldEntry, stderr io.Writer) (string, error) {
	if flag != "" {
		return flag, nil
	}

	inTree := domainsHoldingSystem(root, system)
	fromWorkspace := domainFromWorkspaceLayout(hostDir, scaffolds)

	switch len(inTree) {
	case 1:
		// The repository wins over the workspace: moving a system between domains
		// is a deliberate act, not something a directory name should trigger.
		if fromWorkspace != "" && fromWorkspace != inTree[0] {
			fmt.Fprintf(stderr, "warning: %s is already under %s/%s in the GitOps repository, but the workspace suggests %q; keeping %s — pass --domain to move it deliberately\n",
				system, gitops.DomainsDirName, inTree[0], fromWorkspace, inTree[0])
		}
		return inTree[0], nil
	case 0:
		if fromWorkspace != "" {
			fmt.Fprintf(stderr, "placing %s under %s/%s, from the workspace layout\n", system, gitops.DomainsDirName, fromWorkspace)
			return fromWorkspace, nil
		}
		return "", fmt.Errorf("--domain is required: %s is not in the GitOps repository yet, and the workspace is not laid out as %s/<domain>/%s/, so there is no domain to infer",
			system, gitops.DomainsDirName, system)
	default:
		return "", fmt.Errorf("--domain is required: %s exists under %s", system, strings.Join(inTree, " and "))
	}
}

// domainsHoldingSystem lists the domains the GitOps tree already files this
// system under, sorted. More than one means the name is ambiguous.
func domainsHoldingSystem(root, system string) []string {
	var found []string
	for _, c := range gitops.ListComponents(root) {
		if c.System == system && !slices.Contains(found, c.Domain) {
			found = append(found, c.Domain)
		}
	}
	slices.Sort(found)
	return found
}

// domainFromWorkspaceLayout reads the domain out of the source tree's own shape.
//
// The system host is tried first because it is the system's own directory; a
// block is only a fallback for the --topology case, where no host was discovered.
func domainFromWorkspaceLayout(hostDir string, scaffolds []template.ScaffoldEntry) string {
	if d := domainFromProjectPath(hostDir); d != "" {
		return d
	}
	for _, s := range scaffolds {
		if d := domainFromProjectPath(s.Path); d != "" {
			return d
		}
	}
	return ""
}

// domainFromProjectPath returns the <domain> in
// <...>/domains/<domain>/<system>/<project>, or empty when the path is not laid
// out that way.
//
// The marker directory has to actually be there — gitops.DomainsDirName, the same
// constant the deployment tree uses. Without it nothing is inferred, so a
// workspace with some other shape gets a clear "--domain is required" rather than
// a guess.
func domainFromProjectPath(projectDir string) string {
	if projectDir == "" {
		return ""
	}
	abs, err := filepath.Abs(projectDir)
	if err != nil {
		abs = projectDir
	}
	domainDir := filepath.Dir(filepath.Dir(abs))
	if filepath.Base(filepath.Dir(domainDir)) != gitops.DomainsDirName {
		return ""
	}
	name := filepath.Base(domainDir)
	if name == "." || name == string(filepath.Separator) || name == gitops.DomainsDirName {
		return ""
	}
	return name
}

func selectEnvironments(cfg *gitops.DeployConfig, requested []string) ([]string, error) {
	if len(requested) == 0 {
		// Every environment, in promotion order. The ApplicationSet takes the
		// environment from its cluster generator rather than the path, so an
		// environment without an overlay is an Application pointing at nothing.
		return cfg.PromotionOrder(), nil
	}
	for _, env := range requested {
		if _, err := cfg.Environment(env); err != nil {
			return nil, err
		}
	}
	out := slices.Clone(requested)
	slices.Sort(out)
	return slices.Compact(out), nil
}

// selectComponents narrows the run to the named blocks, or to all of them.
//
// The argument names a topology *component*. A system host is not one — it is
// what emits the topology — so naming the system is a predictable mistake and
// gets its own message: the whole-system run is the no-argument default, and a
// bare "no such component" would not make that obvious.
func selectComponents(m InitModel, requested []string, system string) ([]InitComponent, error) {
	if len(requested) == 0 {
		return m.Components, nil
	}
	byName := make(map[string]InitComponent, len(m.Components))
	names := make([]string, 0, len(m.Components))
	for _, c := range m.Components {
		byName[c.Name] = c
		names = append(names, c.Name)
	}
	var out []InitComponent
	for _, want := range requested {
		c, ok := byName[want]
		if !ok {
			if want == system {
				return nil, fmt.Errorf("%q is this system, not one of its components — run deploy init with no arguments to scaffold the whole system, host included.\nIts components are: %s",
					want, strings.Join(names, ", "))
			}
			return nil, fmt.Errorf("no component %q in the topology; it declares: %s\nRun deploy init with no arguments to scaffold all of them.", want, strings.Join(names, ", "))
		}
		out = append(out, c)
	}
	slices.SortFunc(out, func(a, b InitComponent) int { return strings.Compare(a.Name, b.Name) })
	return out, nil
}

// renderScaffold renders the host template once and the component template once
// per selected component, into a staging tree that mirrors the repository root.
//
// Staging mirrors the repository so a staged path is already the repo-relative
// path the classifier and the commit both need.
// It returns the resolved library reference so the result can record which
// release produced the tree a reviewer is looking at.
func renderScaffold(ctx context.Context, opts InitOptions, facts initFacts, staging string) (string, error) {
	lib, err := template.FetchLibrary(ctx, template.LibraryOptions{
		Version:       opts.TemplateVersion,
		HTTP:          opts.HTTP,
		UserAgent:     opts.UserAgent,
		Stderr:        opts.Stderr,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		GitHubBaseURL: opts.GitHubBaseURL,
	})
	if err != nil {
		return "", err
	}
	defer lib.Close()

	if err := renderOne(opts, facts, lib, TemplateDeployHost, HostDirName, nil, staging); err != nil {
		return "", err
	}
	for _, c := range facts.Selected {
		comp := c
		if err := renderOne(opts, facts, lib, TemplateDeployComponent, c.Name, &comp, staging); err != nil {
			return "", err
		}
	}
	return lib.Ref(), nil
}

// renderOne renders one unit — the host, or one component — into the staging
// tree.
//
// The skeleton is rendered once per environment, because the renderer templates
// paths but does not iterate them, so `overlays/{{ .env }}/kustomization.yaml` is
// the only way to get one directory per environment. mergeRendered then enforces
// that everything outside overlays/ came out identical on every pass.
func renderOne(opts InitOptions, facts initFacts, lib *template.Library, templateName, dirName string, comp *InitComponent, staging string) error {
	tmpl, skeleton, err := lib.Open(templateName)
	if err != nil {
		return err
	}

	dest := filepath.Join(staging, filepath.FromSlash(componentRelPath(facts.Domain, facts.System, dirName)))
	if err := os.MkdirAll(dest, 0o755); err != nil {
		return err
	}

	for _, env := range facts.Environments {
		values, err := resolveInitValues(opts, facts, tmpl, dirName, comp, env)
		if err != nil {
			return fmt.Errorf("%s for %s: %w", templateName, dirName, err)
		}

		pass, err := os.MkdirTemp("", "intropy-render-*")
		if err != nil {
			return err
		}
		err = template.RenderFiltered(skeleton, pass, values, tmpl.Spec.Files)
		if err == nil {
			err = mergeRendered(pass, dest, env)
		}
		os.RemoveAll(pass)
		if err != nil {
			return fmt.Errorf("render %s for %s (%s): %w", templateName, dirName, env, err)
		}
	}
	return nil
}

// resolveInitValues layers the derived facts under the user's input, then injects
// the structures spec.parameters cannot describe.
//
// Facts beat schema defaults; the user beats facts. That order is the whole point
// of ResolveLayered, and this is its first production caller.
func resolveInitValues(opts InitOptions, facts initFacts, tmpl *template.Template, dirName string, comp *InitComponent, env string) (map[string]any, error) {
	base := seedDeclaredParams(tmpl, initSeeds(facts, dirName, comp))

	prompter := template.AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
	values, err := template.ResolveLayered(tmpl, base, opts.Files, opts.Stdin, opts.SetValues, prompter)
	if err != nil {
		return nil, err
	}

	model, err := facts.Model.asMap()
	if err != nil {
		return nil, err
	}
	reserved := map[string]any{
		template.ReservedEnvKey:      env,
		template.ReservedTopologyKey: model,
		template.ReservedGitopsKey:   facts.gitopsMap(dirName, env),
	}
	if comp != nil {
		componentMap, err := toMap(comp)
		if err != nil {
			return nil, err
		}
		reserved[template.ReservedComponentKey] = componentMap
		reserved[template.ReservedScaffoldKey] = facts.scaffoldValues(comp.Name)
	}
	if err := template.InjectReserved(tmpl, values, reserved); err != nil {
		return nil, err
	}
	return values, nil
}

// initSeeds is every fact the CLI can derive, keyed by the parameter name a
// template would declare for it.
func initSeeds(facts initFacts, dirName string, comp *InitComponent) map[string]any {
	seeds := map[string]any{
		"domain":             facts.Domain,
		"system":             facts.System,
		"hostName":           HostDirName,
		"registry":           facts.Registry,
		"argocdAppNamespace": facts.AppNamespace,
		"provider":           facts.Platform.Provider,
		"pubsub":             facts.Platform.Pubsub,
		"secretStore":        facts.Platform.SecretStore,
	}
	// Only when unambiguous. Guessing between two brokers would put the wrong
	// name in a Component that the generated C# then fails to resolve.
	if len(facts.Model.PubSubs) == 1 {
		seeds["pubsubName"] = facts.Model.PubSubs[0].Name
	}
	if comp != nil {
		seeds["name"] = comp.Name
		seeds["kind"] = comp.Kind
		seeds["appId"] = comp.AppID
		seeds["workload"] = comp.Workload
		if comp.Dir != "" {
			seeds["sourceDir"] = comp.Dir
		}
	} else {
		seeds["name"] = dirName
		seeds["appId"] = dirName
	}
	return seeds
}

// seedDeclaredParams keeps only the seeds the template declares as parameters.
//
// An undeclared key would sail past JSON Schema validation and land in the value
// map anyway, which is how a template silently acquires a dependency nobody
// documented.
func seedDeclaredParams(tmpl *template.Template, seeds map[string]any) map[string]any {
	base := make(map[string]any, len(seeds))
	for _, f := range tmpl.Fields() {
		if v, ok := seeds[f.Name]; ok && !isBlank(v) {
			base[f.Name] = v
		}
	}
	return base
}

// isBlank drops an empty derived fact so the template's own default still
// applies: an unset platform.pubsub must not override `default: rabbitmq`.
func isBlank(v any) bool {
	s, ok := v.(string)
	return ok && s == ""
}

func (f initFacts) gitopsMap(component, env string) map[string]any {
	return map[string]any{
		"domain":             f.Domain,
		"system":             f.System,
		"component":          component,
		"env":                env,
		"host":               HostDirName,
		"registry":           f.Registry,
		"argocdAppNamespace": f.AppNamespace,
		"environments":       f.Environments,
		"platform": map[string]any{
			"provider":    f.Platform.Provider,
			"pubsub":      f.Platform.Pubsub,
			"secretStore": f.Platform.SecretStore,
		},
	}
}

// scaffoldValues is the component's recorded template values, or an empty map so
// a skeleton reading .scaffold.x never fails on a missing record.
func (f initFacts) scaffoldValues(component string) map[string]any {
	if s, ok := f.Scaffolds[component]; ok && s.Values != nil {
		return s.Values
	}
	return map[string]any{}
}

func toMap(v any) (map[string]any, error) {
	raw, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	var out map[string]any
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, err
	}
	return out, nil
}

type publishScaffoldOptions struct {
	StagingDir string
	Dest       *destTree
	Actions    []FileAction
	Rels       []string
	Branch     string
	Facts      initFacts
}

// publishedScaffold is what a successful push produced.
type publishedScaffold struct {
	Revision string

	// Placeholders are scanned from the working tree *while the branch is still
	// checked out*. Scanning afterwards would find nothing: restoring the default
	// branch takes the new files back out of the working tree.
	Placeholders []Placeholder
}

// publishScaffold writes the staged files on a fresh branch and pushes it.
//
// Never to the default branch: the tree is full of placeholders and unpinned
// images, and the ApplicationSet would generate Applications for it the moment it
// landed. A branch is the reviewable artefact.
//
// Publish is not reused: it is wired to a Plan and its rebase-retry loop is for a
// one-line contended edit. A fresh branch that is rejected already exists on the
// remote, which is a clear error rather than something to retry.
func publishScaffold(ctx context.Context, opts InitOptions, repo *gitops.Repository, p publishScaffoldOptions) (publishedScaffold, error) {
	start := gitops.RemoteName + "/" + repo.Branch
	if err := repo.Git.CreateBranch(ctx, p.Branch, start); err != nil {
		return publishedScaffold{}, err
	}
	// Unconditionally, on success and on failure alike: the refresh on the next
	// Open resets whatever branch is current to the default branch's remote head,
	// so leaving the checkout here would silently discard these commits.
	defer func() {
		if err := repo.Git.Switch(ctx, repo.Branch); err != nil {
			fmt.Fprintf(opts.Stderr, "warning: could not restore %s in the cached checkout: %v\n", repo.Branch, err)
		}
	}()

	written, err := applyStaged(p.StagingDir, p.Dest, p.Actions)
	if err != nil {
		return publishedScaffold{}, err
	}
	// Only the paths staged, never `add -A`: the checkout is shared, and a
	// concurrent run's debris is not ours to commit.
	if err := repo.Git.Add(ctx, written...); err != nil {
		return publishedScaffold{}, err
	}
	// The scaffold is reviewed as a branch, and a reviewer reads the file list as
	// the whole of what this command did. It has to actually be that.
	if err := assertStagedIsExactly(ctx, repo.Git, written); err != nil {
		return publishedScaffold{}, err
	}
	if err := repo.Git.Commit(ctx, scaffoldSubject(p.Facts, len(written)), scaffoldTrailers(p.Facts, opts.CliVersion)); err != nil {
		return publishedScaffold{}, err
	}
	if err := assertCommittedIsExactly(ctx, repo.Git, written); err != nil {
		return publishedScaffold{}, err
	}
	if err := repo.Git.Push(ctx, gitops.RemoteName, "HEAD:refs/heads/"+p.Branch); err != nil {
		return publishedScaffold{}, fmt.Errorf("push %s: %w\n\nA rejection here usually means the branch already exists on the remote. Delete it, or merge the open review first.", p.Branch, err)
	}

	revision, err := repo.Git.HEAD(ctx)
	if err != nil {
		return publishedScaffold{}, err
	}
	// While the branch is still current — the deferred switch above takes these
	// files back out of the working tree.
	placeholders, err := scanPlaceholders(repo.Root, p.Rels)
	if err != nil {
		return publishedScaffold{}, err
	}
	return publishedScaffold{Revision: revision, Placeholders: placeholders}, nil
}

func scaffoldSubject(facts initFacts, files int) string {
	return fmt.Sprintf("deploy-init(%s): scaffold %d file%s under %s", facts.System, files, plural(files), facts.Domain)
}

func scaffoldTrailers(facts initFacts, cliVersion string) string {
	trailers := []git.Trailer{
		{Key: TrailerDomain, Value: facts.Domain},
		{Key: TrailerSystem, Value: facts.System},
	}
	for _, c := range facts.Selected {
		trailers = append(trailers, git.Trailer{Key: TrailerComponent, Value: c.Name})
	}
	if who := committer(); who != "" {
		trailers = append(trailers, git.Trailer{Key: TrailerBy, Value: who})
	}
	if cliVersion != "" {
		trailers = append(trailers, git.Trailer{Key: TrailerCli, Value: cliVersion})
	}

	lines := make([]string, 0, len(trailers))
	for _, t := range trailers {
		lines = append(lines, t.String())
	}
	return strings.Join(lines, "\n")
}

// reportInit writes the action table, then what remains to be done.
func reportInit(out output, result InitResult, actions []FileAction, planOnly bool) error {
	if out.Format == OutputJSON {
		enc := json.NewEncoder(out.Stdout)
		enc.SetIndent("", "  ")
		if err := enc.Encode(result); err != nil {
			return fmt.Errorf("write JSON result: %w", err)
		}
		return nil
	}

	for _, a := range actions {
		fmt.Fprintf(out.Stdout, "  %-12s %s\n", a.Action, a.Rel)
	}
	fmt.Fprintf(out.Stdout, "\n%s\n", summariseActions(actions))

	switch {
	case planOnly:
		fmt.Fprintln(out.Stdout, "nothing written (--plan)")
	case result.Applied:
		fmt.Fprintf(out.Stdout, "pushed branch %s at %s\n", result.Branch, git.ShortSHA(result.Revision))
	default:
		fmt.Fprintln(out.Stdout, "already onboarded; nothing to write")
	}

	if skipped := skippedPaths(actions); len(skipped) > 0 {
		fmt.Fprintf(out.Stdout, "\n%d file%s already differ and were left alone; --force overwrites them:\n",
			len(skipped), plural(len(skipped)))
		for _, rel := range skipped {
			fmt.Fprintf(out.Stdout, "  %s\n", rel)
		}
	}

	reportPlaceholders(out, result.Placeholders)
	return nil
}

func skippedPaths(actions []FileAction) []string {
	var out []string
	for _, a := range actions {
		if a.Action == ActionSkipExists {
			out = append(out, a.Rel)
		}
	}
	return out
}

package deploy

import (
	"fmt"
	"maps"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"gopkg.in/yaml.v3"
)

// localConfigFileName is the state file int local keeps at the workspace root,
// beside the host's .intropy/scaffold.json. It is checked in: the whole team
// runs the same local topology, and CI runs non-interactively.
const localConfigFileName = ".intropy/local.yaml"

func localConfigPath(sourceDir string) string {
	return filepath.Join(sourceDir, filepath.FromSlash(localConfigFileName))
}

// localConfig is .intropy/local.yaml: the team's recorded decision of which
// fixture each connector binds to on the local cluster.
type localConfig struct {
	Bindings map[string]string
}

type localConfigFile struct {
	Connectors map[string]string `yaml:"connectors"`
}

// loadLocalConfig reads the state file. A missing file is an empty config, not
// an error — the first run of a workspace is exactly that case.
func loadLocalConfig(path string) (localConfig, error) {
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return localConfig{}, nil
	}
	if err != nil {
		return localConfig{}, fmt.Errorf("read %s: %w", path, err)
	}
	var f localConfigFile
	if err := yaml.Unmarshal(data, &f); err != nil {
		return localConfig{}, fmt.Errorf("parse %s: %w", path, err)
	}
	return localConfig{Bindings: f.Connectors}, nil
}

// saveLocalConfig writes the state file with keys sorted, so a re-record
// produces a minimal, stable diff.
func saveLocalConfig(path string, cfg localConfig) error {
	var sb strings.Builder
	sb.WriteString("# which fixture each connector binds to on the local cluster;\n")
	sb.WriteString("# written by 'intropy int local' and checked in so the team renders the same\n")
	sb.WriteString("connectors:\n")
	for _, name := range slices.Sorted(maps.Keys(cfg.Bindings)) {
		fmt.Fprintf(&sb, "  %s: %s\n", name, cfg.Bindings[name])
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	if err := os.WriteFile(path, []byte(sb.String()), 0o644); err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	return nil
}

package deploy

import (
	"encoding/json"
	"fmt"
	"maps"
	"path/filepath"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// The Kubernetes workload a block runs as.
//
// An extractor is scheduled: it wakes, pulls from its source and exits, which is
// a CronJob. Every other block reacts to messages or requests and must stay
// resident. This is what the hand-written customer repos already do — fluxia and
// entrovia both run their extractors as CronJobs — so deriving it from the
// topology is reproducing an existing convention, not inventing one.
const (
	WorkloadCronJob    = "cronjob"
	WorkloadDeployment = "deployment"
)

// blockKindExtractor is the topology's block kind for a scheduled extractor.
// Records spell kinds inconsistently (camelCase from one emitter, kebab-case
// after the frontend normalises), so the comparison folds case.
const blockKindExtractor = "extractor"

// InitModel is the topology view a manifest skeleton sees under the reserved
// "topology" key: derived, flattened and sorted.
//
// Raw topology.Topology is unsuitable for two reasons. Its APIs, Provides and
// Consumes are json.RawMessage whose element shape is not finalised, so a
// skeleton ranging over them would break when it is. And neither Go map
// iteration nor host emission order is stable, while idempotent scaffolding
// depends on a re-render being byte-identical — so everything here is sorted.
type InitModel struct {
	System     string          `json:"system"`
	Components []InitComponent `json:"components"`
	PubSubs    []InitPubSub    `json:"pubsubs"`
	Topics     []InitTopic     `json:"topics"`
	Connectors []InitConnector `json:"connectors"`
}

// InitComponent is one block as the manifests need it.
type InitComponent struct {
	// Name is the topology component name, which is also the GitOps component
	// directory segment.
	Name string `json:"name"`

	// Kind is the topology block kind, carried through verbatim for labels.
	Kind string `json:"kind"`

	// AppID is the Dapr app-id: what a Component's scopes list and what the
	// generated C# resolves components by. Falls back to Name when no scaffold
	// record declares one.
	AppID string `json:"appId"`

	// Workload is WorkloadCronJob or WorkloadDeployment.
	Workload string `json:"workload"`

	// Dir is the component's source directory relative to the system root, when
	// a scaffold record was matched. Empty otherwise — a missing record is a
	// warning, not a failure, so the manifests still generate.
	Dir string `json:"dir,omitempty"`

	Topics     []string `json:"topics,omitempty"`
	Connectors []string `json:"connectors,omitempty"`
}

// InitPubSub is one Dapr pub/sub component the system needs.
type InitPubSub struct {
	Name   string   `json:"name"`
	Topics []string `json:"topics,omitempty"`

	// AppIDs is what belongs in the Component's scopes: every app-id the
	// topology says publishes to or subscribes from one of its topics.
	AppIDs []string `json:"appIds,omitempty"`
}

// InitTopic is a declared topic, with the ends resolved to app-ids.
type InitTopic struct {
	PubSub      string   `json:"pubsub"`
	Topic       string   `json:"topic"`
	Contract    string   `json:"contract,omitempty"`
	Publishers  []string `json:"publishers,omitempty"`
	Subscribers []string `json:"subscribers,omitempty"`
}

// InitConnector is an external integration point. The topology mints only
// its name: the deployed Dapr binding type, address, host and credential are
// environment-owned deployment configuration, which is exactly why they are
// placeholders in the rendered manifests.
type InitConnector struct {
	Name           string   `json:"name"`
	ExternalSystem string   `json:"externalSystem,omitempty"`
	Directions     []string `json:"directions,omitempty"`
	AppIDs         []string `json:"appIds,omitempty"`
}

// newInitModel derives the model from a decoded topology record and whatever
// scaffold records were found in the workspace.
func newInitModel(t *topology.Topology, scaffolds []template.ScaffoldEntry) InitModel {
	appIDs, dirs := joinScaffolds(t.Components, matchScaffolds(t.Components, scaffolds))

	m := InitModel{System: t.System}
	m.Components = buildComponents(t.Components, appIDs, dirs)
	m.Topics = buildTopics(t.Topics, appIDs)
	m.PubSubs = buildPubSubs(t, appIDs)
	m.Connectors = buildConnectors(t.Connectors, appIDs)
	return m
}

// asMap renders the model as plain maps and slices.
//
// Injected reserved values go through this so a skeleton's `index`, `range` and
// sprig calls see uniform map[string]any — a Go struct behaves differently
// under `index` and would make the template author's life needlessly subtle.
func (m InitModel) asMap() (map[string]any, error) {
	raw, err := json.Marshal(m)
	if err != nil {
		return nil, fmt.Errorf("encode topology model: %w", err)
	}
	var out map[string]any
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, fmt.Errorf("decode topology model: %w", err)
	}
	return out, nil
}

// matchScaffolds pairs each topology component with its scaffold record.
//
// The join is by convention, and the toolchain uses two conventions: a
// component's directory basename, and its scaffold record's values.appId. Both
// are matched — directory first — because a record found by either is better
// than manifests generated without one. A component with no record is simply
// absent from the result: that is a warning, not a failure.
func matchScaffolds(components []topology.Component, scaffolds []template.ScaffoldEntry) map[string]template.ScaffoldEntry {
	byDir := make(map[string]template.ScaffoldEntry, len(scaffolds))
	byAppID := make(map[string]template.ScaffoldEntry, len(scaffolds))
	for _, s := range scaffolds {
		byDir[filepath.Base(s.Path)] = s
		if id := scaffoldString(s, "appId"); id != "" {
			byAppID[id] = s
		}
	}

	out := make(map[string]template.ScaffoldEntry, len(components))
	for _, c := range components {
		if match, found := byDir[c.Name]; found {
			out[c.Name] = match
			continue
		}
		if match, found := byAppID[c.Name]; found {
			out[c.Name] = match
		}
	}
	return out
}

// joinScaffolds reduces the matched records to the two facts the model needs.
func joinScaffolds(components []topology.Component, matched map[string]template.ScaffoldEntry) (appIDs, dirs map[string]string) {
	appIDs = make(map[string]string, len(components))
	dirs = make(map[string]string, len(components))
	for _, c := range components {
		match, found := matched[c.Name]
		if !found {
			continue
		}
		dirs[c.Name] = filepath.Base(match.Path)
		if id := scaffoldString(match, "appId"); id != "" {
			appIDs[c.Name] = id
		}
	}
	return appIDs, dirs
}

func scaffoldString(s template.ScaffoldEntry, key string) string {
	v, _ := s.Values[key].(string)
	return v
}

// appIDOf resolves a component name to an app-id.
//
// A name with no entry is returned unchanged. That covers two cases: a component
// with no scaffold record, and a name that is not a component of this system at
// all — Topic.Publishers and Topic.Subscribers may reference a block deployed
// elsewhere, and denying it access to the broker would be worse than scoping a
// name we cannot resolve.
func appIDOf(appIDs map[string]string, name string) string {
	if id, ok := appIDs[name]; ok {
		return id
	}
	return name
}

func buildComponents(components []topology.Component, appIDs, dirs map[string]string) []InitComponent {
	out := make([]InitComponent, 0, len(components))
	for _, c := range components {
		ic := InitComponent{
			Name:     c.Name,
			Kind:     c.Kind,
			AppID:    appIDOf(appIDs, c.Name),
			Workload: workloadFor(c.Kind),
			Dir:      dirs[c.Name],
		}

		topics := map[string]bool{}
		for _, s := range c.Subscribes {
			topics[s.Topic] = true
		}
		for _, p := range c.Publishes {
			topics[p.Topic] = true
		}
		ic.Topics = sortedKeys(topics)

		conns := map[string]bool{}
		for _, u := range c.Connectors {
			conns[u.Connector] = true
		}
		ic.Connectors = sortedKeys(conns)

		out = append(out, ic)
	}
	slices.SortFunc(out, func(a, b InitComponent) int { return strings.Compare(a.Name, b.Name) })
	return out
}

// workloadFor maps a block kind to its Kubernetes workload. Anything that is not
// an extractor stays resident, which is the safe default: a block wrongly run as
// a CronJob would silently stop consuming.
func workloadFor(kind string) string {
	if strings.EqualFold(kind, blockKindExtractor) {
		return WorkloadCronJob
	}
	return WorkloadDeployment
}

func buildTopics(topics []topology.Topic, appIDs map[string]string) []InitTopic {
	out := make([]InitTopic, 0, len(topics))
	for _, t := range topics {
		out = append(out, InitTopic{
			PubSub:      t.PubSub,
			Topic:       t.Topic,
			Contract:    t.Contract,
			Publishers:  sortedAppIDs(appIDs, t.Publishers),
			Subscribers: sortedAppIDs(appIDs, t.Subscribers),
		})
	}
	slices.SortFunc(out, func(a, b InitTopic) int {
		if c := strings.Compare(a.PubSub, b.PubSub); c != 0 {
			return c
		}
		return strings.Compare(a.Topic, b.Topic)
	})
	return out
}

// buildPubSubs collects the distinct pub/sub components the system needs.
//
// Names are gathered from the top-level topics *and* from each component's
// inline references, because a component may publish to a topic the record's
// topics[] table does not list — and a pub/sub nobody declared is still one the
// sidecar will try to resolve.
func buildPubSubs(t *topology.Topology, appIDs map[string]string) []InitPubSub {
	topics := map[string]map[string]bool{}
	scopes := map[string]map[string]bool{}

	note := func(pubsub, topic string, users ...string) {
		if pubsub == "" {
			return
		}
		if topics[pubsub] == nil {
			topics[pubsub] = map[string]bool{}
			scopes[pubsub] = map[string]bool{}
		}
		if topic != "" {
			topics[pubsub][topic] = true
		}
		for _, u := range users {
			if u != "" {
				scopes[pubsub][appIDOf(appIDs, u)] = true
			}
		}
	}

	for _, top := range t.Topics {
		note(top.PubSub, top.Topic, append(slices.Clone(top.Publishers), top.Subscribers...)...)
	}
	for _, c := range t.Components {
		for _, s := range c.Subscribes {
			note(s.PubSub, s.Topic, c.Name)
		}
		for _, p := range c.Publishes {
			note(p.PubSub, p.Topic, c.Name)
		}
	}

	out := make([]InitPubSub, 0, len(topics))
	for _, name := range slices.Sorted(maps.Keys(topics)) {
		out = append(out, InitPubSub{
			Name:   name,
			Topics: sortedKeys(topics[name]),
			AppIDs: sortedKeys(scopes[name]),
		})
	}
	return out
}

func buildConnectors(connectors []topology.Connector, appIDs map[string]string) []InitConnector {
	out := make([]InitConnector, 0, len(connectors))
	for _, c := range connectors {
		out = append(out, InitConnector{
			Name:           c.Name,
			ExternalSystem: c.ExternalSystem,
			Directions:     slices.Sorted(slices.Values(c.Directions)),
			AppIDs:         sortedAppIDs(appIDs, c.UsedBy),
		})
	}
	slices.SortFunc(out, func(a, b InitConnector) int { return strings.Compare(a.Name, b.Name) })
	return out
}

func sortedAppIDs(appIDs map[string]string, names []string) []string {
	if len(names) == 0 {
		return nil
	}
	set := make(map[string]bool, len(names))
	for _, n := range names {
		set[appIDOf(appIDs, n)] = true
	}
	return sortedKeys(set)
}

// sortedKeys returns a set's members in sorted order, or nil when empty so the
// omitempty JSON tags elide the field rather than emitting [].
func sortedKeys(set map[string]bool) []string {
	if len(set) == 0 {
		return nil
	}
	return slices.Sorted(maps.Keys(set))
}

// Package topology models the declared system topology an integration
// system's host emits. The record declares the system's shape: its components
// (blocks) and the wiring between them, expressed inline on each component —
// the topics it subscribes to and publishes on, the API contracts it provides
// and consumes, and the external connectors it uses. Top-level topics[] and
// connectors[] sections carry the shared metadata (contracts, external
// systems) those inline references point at.
//
// The record carries only minted facts: the Dapr binding a connector deploys
// as (its spec.type, address, credentials) is environment-owned deployment
// configuration in the GitOps repo, and an extractor's cadence is its CronJob
// there. Neither appears here.
//
// The CLI never derives a topology itself: the system host's `graph` verb
// prints the record — JSON only, on stdout — and consumers decode that stream.
package topology

import (
	"encoding/json"
	"fmt"
	"io"
)

const (
	// APIVersion is the topology schema this CLI understands. A record with
	// any other apiVersion is an error, not a guess.
	APIVersion = "topology.intropy.io/v1"

	// Kind is the expected document kind under APIVersion.
	Kind = "SystemTopology"
)

// Topology is one system's declared graph. Wiring is inlined on each component
// rather than kept in a separate edge list: a component names the topics it
// subscribes to and publishes on and the connectors it uses. The top-level
// Topics and Connectors sections are lookup tables the inline references
// resolve against (contract, external system).
type Topology struct {
	APIVersion string      `json:"apiVersion"`
	Kind       string      `json:"kind,omitempty"`
	System     string      `json:"system"`
	Components []Component `json:"components,omitempty"`
	Topics     []Topic     `json:"topics,omitempty"`
	Connectors []Connector `json:"connectors,omitempty"`
	Contracts  []Contract  `json:"contracts,omitempty"`
	// APIs, and each component's Provides/Consumes below, are the contract
	// (request/response) surfaces. Their element shape is not yet finalized,
	// so they are parsed opaquely: preserved for round-tripping to the
	// frontend without asserting a schema the CLI does not yet render.
	APIs []json.RawMessage `json:"apis,omitempty"`
}

// Component is a deployable block of the system. Kind is the block type
// (extractor, loader, transactionalIntegration, …). A component's directory,
// which joins it to its .intropy/scaffold.json project, is its Name relative
// to the system root.
type Component struct {
	Name       string         `json:"name"`
	Kind       string         `json:"kind"`
	Subscribes []TopicRef     `json:"subscribes,omitempty"`
	Publishes  []Publication  `json:"publishes,omitempty"`
	Connectors []ConnectorUse `json:"connectors,omitempty"`
	// Provides/Consumes are contract surfaces, parsed opaquely (see APIs).
	Provides []json.RawMessage `json:"provides,omitempty"`
	Consumes []json.RawMessage `json:"consumes,omitempty"`
}

// TopicRef is a component's subscription to a pub/sub topic.
type TopicRef struct {
	PubSub string `json:"pubsub"`
	Topic  string `json:"topic"`
}

// Publication is a component's output onto a pub/sub topic. Port names the
// component output the message leaves through.
type Publication struct {
	Port   string `json:"port,omitempty"`
	PubSub string `json:"pubsub"`
	Topic  string `json:"topic"`
}

// ConnectorUse is a component's use of an external connector. Direction is
// "in" (external → component) or "out" (component → external).
type ConnectorUse struct {
	Connector string `json:"connector"`
	Direction string `json:"direction"`
}

// Topic is a declared pub/sub topic: the metadata for a (PubSub, Topic) pair
// components reference. Contract is the message contract it carries;
// Publishers/Subscribers name the components on each end.
type Topic struct {
	PubSub      string   `json:"pubsub"`
	Topic       string   `json:"topic"`
	Contract    string   `json:"contract,omitempty"`
	Publishers  []string `json:"publishers,omitempty"`
	Subscribers []string `json:"subscribers,omitempty"`
}

// Contract is a message contract in the system's registry, keyed by Name —
// the same fully-qualified type name Topic.Contract references. ShortName is
// the bare type name (the join key to a scaffold record's values.contract).
// Schema is the contract's JSON Schema as the host emitted it; the CLI passes
// it through to the frontend without interpreting it. Fingerprint identifies
// the schema shape (a hash over its canonical form), so equal fingerprints
// mean equal shapes across systems.
type Contract struct {
	Name        string          `json:"name"`
	Kind        string          `json:"kind,omitempty"`
	ShortName   string          `json:"shortName,omitempty"`
	MediaType   string          `json:"mediaType,omitempty"`
	Fingerprint string          `json:"fingerprint,omitempty"`
	Schema      json.RawMessage `json:"schema,omitempty"`
}

// Connector is an external system integration point. The name is its whole
// identity — the deployed Dapr binding type, address, and credentials are
// environment-owned deployment configuration, never part of the record.
// ExternalSystem is the system it fronts, Directions the directions it is
// wired in, and UsedBy the components that use it.
type Connector struct {
	Name           string   `json:"name"`
	ExternalSystem string   `json:"externalSystem,omitempty"`
	Directions     []string `json:"directions,omitempty"`
	UsedBy         []string `json:"usedBy,omitempty"`
}

// Entry is one system's topology plus the workspace directory it belongs to,
// flattened into one self-describing JSON document for the API.
type Entry struct {
	Path string `json:"path"`
	Topology
}

// Decode parses a topology record from r (typically a host `graph` verb's
// stdout). A record whose apiVersion this CLI does not understand is an
// error, not a guess. Callers wrap the error with the record's origin.
func Decode(r io.Reader) (*Topology, error) {
	var t Topology
	if err := json.NewDecoder(r).Decode(&t); err != nil {
		return nil, fmt.Errorf("parse topology record: %w", err)
	}
	if t.APIVersion != APIVersion {
		return nil, fmt.Errorf("unsupported topology apiVersion %q (this CLI understands %q)",
			t.APIVersion, APIVersion)
	}
	return &t, nil
}

