package deploy

import (
	"fmt"
	"maps"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"gopkg.in/yaml.v3"
)

// deployValuesFileName is the state file deploy init keeps at the workspace
// root, beside the host's .intropy/scaffold.json. It is checked in: the whole
// team scaffolds the same connectors, and CI runs non-interactively.
const deployValuesFileName = ".intropy/deploy-values.yaml"

// legacyLocalConfigFileName is the state file int local kept, absorbed into
// deploy-values.yaml: its bindings become the "local" environment's entries.
const legacyLocalConfigFileName = ".intropy/local.yaml"

func deployValuesPath(sourceDir string) string {
	return filepath.Join(sourceDir, filepath.FromSlash(deployValuesFileName))
}

// deployValues is .intropy/deploy-values.yaml: the team's recorded decision of
// which Dapr binding each connector deploys as, per environment. "local" is
// one environment among them; its values name fixtures rather than binding
// types, but the mechanism is the same.
type deployValues struct {
	// Connectors maps connector name to environment to binding.
	Connectors map[string]map[string]string
}

type deployValuesFile struct {
	Connectors map[string]map[string]string `yaml:"connectors"`
}

// loadDeployValues reads the state file. A missing file is an empty config,
// not an error — the first run of a workspace is exactly that case.
func loadDeployValues(path string) (deployValues, error) {
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return deployValues{}, nil
	}
	if err != nil {
		return deployValues{}, fmt.Errorf("read %s: %w", path, err)
	}
	var f deployValuesFile
	if err := yaml.Unmarshal(data, &f); err != nil {
		return deployValues{}, fmt.Errorf("parse %s: %w", path, err)
	}
	return deployValues{Connectors: f.Connectors}, nil
}

// saveDeployValues writes the state file with keys sorted at both levels, so
// a re-record produces a minimal, stable diff.
func saveDeployValues(path string, vals deployValues) error {
	var sb strings.Builder
	sb.WriteString("# which Dapr binding each connector deploys as, per environment;\n")
	sb.WriteString("# written by 'intropy deploy init' and checked in so the team scaffolds the same\n")
	sb.WriteString("connectors:\n")
	for _, name := range slices.Sorted(maps.Keys(vals.Connectors)) {
		fmt.Fprintf(&sb, "  %s:\n", name)
		for _, env := range slices.Sorted(maps.Keys(vals.Connectors[name])) {
			fmt.Fprintf(&sb, "    %s: %s\n", env, vals.Connectors[name][env])
		}
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	if err := os.WriteFile(path, []byte(sb.String()), 0o644); err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	return nil
}

// migrateLegacyLocalConfig folds an old .intropy/local.yaml into the values
// file as the local environment's bindings, and removes the legacy file.
// Both files absent is the first-run case and not an error; both present is
// left alone — merging two sources silently would guess at which one is
// newer, so the resolver's catalog validation surfaces any conflict instead.
func migrateLegacyLocalConfig(sourceDir string, stderr io.Writer) error {
	legacy := filepath.Join(sourceDir, filepath.FromSlash(legacyLocalConfigFileName))
	data, err := os.ReadFile(legacy)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("read %s: %w", legacy, err)
	}
	current := deployValuesPath(sourceDir)
	if _, err := os.Stat(current); err == nil {
		fmt.Fprintf(stderr, "note: both %s and %s exist; leaving the migration alone\n", legacyLocalConfigFileName, deployValuesFileName)
		return nil
	}

	var legacyFile struct {
		Connectors map[string]string `yaml:"connectors"`
	}
	if err := yaml.Unmarshal(data, &legacyFile); err != nil {
		return fmt.Errorf("parse %s: %w", legacy, err)
	}
	vals := deployValues{Connectors: map[string]map[string]string{}}
	for name, binding := range legacyFile.Connectors {
		vals.Connectors[name] = map[string]string{localEnv: binding}
	}
	if err := saveDeployValues(current, vals); err != nil {
		return err
	}
	if err := os.Remove(legacy); err != nil {
		return fmt.Errorf("remove migrated %s: %w", legacy, err)
	}
	fmt.Fprintf(stderr, "migrated %s into %s\n", legacyLocalConfigFileName, deployValuesFileName)
	return nil
}

package deploy

import (
	"fmt"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// resolveConnectorBindings decides which Dapr binding each topology connector
// deploys as, for every environment being scaffolded.
//
// The catalog the answers are chosen from and validated against comes from the
// fetched library: spec.local.fixtures for the local environment, spec.bindings
// for every other — so the menu, the validation and the rendered skeletons can
// never drift apart. Recorded answers live in .intropy/deploy-values.yaml and
// are the previous environment's default when a new one is asked: a binding
// type rarely differs between GitOps environments, so a re-ask is usually
// enter-enter-enter.
//
// An unbound connector is never silently skipped. Local mode fails — a fixture
// must bind. GitOps mode binds nothing and reports the connector as pending:
// the skeleton renders its REPLACE-ME scaffold, exactly as before the question
// existed.
func resolveConnectorBindings(opts InitOptions, facts initFacts, lib *template.Library) (map[string]map[string]string, error) {
	if err := migrateLegacyLocalConfig(opts.SourceDir, opts.Stderr); err != nil {
		return nil, err
	}
	path := deployValuesPath(opts.SourceDir)
	vals, err := loadDeployValues(path)
	if err != nil {
		return nil, err
	}
	if vals.Connectors == nil {
		vals.Connectors = map[string]map[string]string{}
	}

	catalogs, err := bindingCatalogs(lib)
	if err != nil {
		return nil, err
	}

	// NewMenuPrompter rather than SelectPrompter: the connector question is
	// answered from piped stdin in tests and scripts too, and --no-input is
	// still what turns prompting off. The answer is persisted to a checked-in
	// file, so a piped answer is as reviewable as a typed one.
	var prompter *template.MenuPrompter
	if !opts.NoInput {
		prompter = template.NewMenuPrompter(opts.Stdin, opts.Stderr)
	}

	// envs is promotion order; local mode has exactly one. Answers settled in
	// one environment are the defaults for the next.
	settled := map[string]string{}
	changed := false
	for _, env := range facts.Environments {
		catalog := catalogs[env]
		for _, conn := range facts.Model.Connectors {
			if recorded := vals.Connectors[conn.Name][env]; recorded != "" {
				if !slices.Contains(catalog, recorded) {
					return nil, fmt.Errorf("connector %s is bound to %q for %s in %s, which %s does not offer; the catalog is: %s\nedit the file, or delete the entry to be asked again",
						conn.Name, recorded, env, path, TemplateDeployComponent, strings.Join(catalog, ", "))
				}
				settled[conn.Name] = recorded
				continue
			}
			if prompter == nil {
				if opts.Mode == ModeLocal {
					return nil, fmt.Errorf("connector %s has no local binding in %s\nrun 'intropy deploy init --local %s' interactively, or add it to the file",
						conn.Name, path, facts.System)
				}
				fmt.Fprintf(opts.Stderr, "note: connector %s has no binding for %s; its manifests keep the REPLACE-ME scaffold\n", conn.Name, env)
				continue
			}
			options := catalog
			if prev := settled[conn.Name]; prev != "" && slices.Contains(catalog, prev) {
				options = append([]string{prev}, slices.DeleteFunc(slices.Clone(catalog), func(c string) bool { return c == prev })...)
			}
			heading := fmt.Sprintf("connector %s (external system %s) — which binding for %s?", conn.Name, conn.ExternalSystem, env)
			choice, err := prompter.Select(heading, options)
			if err != nil {
				return nil, fmt.Errorf("read binding for connector %s: %w", conn.Name, err)
			}
			if vals.Connectors[conn.Name] == nil {
				vals.Connectors[conn.Name] = map[string]string{}
			}
			vals.Connectors[conn.Name][env] = choice
			settled[conn.Name] = choice
			changed = true
		}
	}

	// A binding the topology no longer declares is harmless — the state file
	// may be shared with a branch that still has it — but worth a note.
	for name := range vals.Connectors {
		if !slices.ContainsFunc(facts.Model.Connectors, func(c InitConnector) bool { return c.Name == name }) {
			fmt.Fprintf(opts.Stderr, "note: %s binds %s, which the topology no longer declares\n", deployValuesFileName, name)
		}
	}

	if !changed {
		return vals.Connectors, nil
	}
	if err := saveDeployValues(path, vals); err != nil {
		return nil, err
	}
	fmt.Fprintf(opts.Stderr, "recorded connector bindings in %s\n", path)
	return vals.Connectors, nil
}

// bindingCatalogs maps each environment to the catalog its answers come from.
// The local environment binds to fixtures — the stub servers the k3s scripts
// install — from spec.local.fixtures; every other environment binds to a Dapr
// binding type from spec.bindings. A release that ships neither cannot answer
// the question, so that is a hard error naming the release rather than a menu
// with no choices.
func bindingCatalogs(lib *template.Library) (map[string][]string, error) {
	tmpl, _, err := lib.Open(TemplateDeployComponent)
	if err != nil {
		return nil, err
	}
	if tmpl.Spec.Local == nil || len(tmpl.Spec.Local.Fixtures) == 0 {
		return nil, fmt.Errorf("%s declares no fixture catalog (spec.local.fixtures on %s)\nuse --template-version to pin a library release that ships one", lib.Ref(), TemplateDeployComponent)
	}
	out := map[string][]string{localEnv: tmpl.Spec.Local.Fixtures}
	if len(tmpl.Spec.Bindings) > 0 {
		// Every environment is one of these two; a library without
		// spec.bindings is a release older than the GitOps question, and
		// those environments fall back to placeholders with no menu.
		for _, env := range libEnvironments {
			_ = env
		}
	}
	return out, nil
}

